--

CREATE FUNCTION public.soft_delete_customer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update the record instead of deleting it
    UPDATE customer 
    SET deleted_at = CURRENT_TIMESTAMP, is_active = 0 
    WHERE customer_id = OLD.customer_id;
    
    -- Return NULL to cancel the actual physical DELETE operation
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.soft_delete_customer() OWNER TO "MyUser";

