-- Name: trgf_after_reservation_update(); Type: FUNCTION; Schema: public; Owner: MyUser
--

CREATE FUNCTION public.trgf_after_reservation_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_confirmed_id INT;
    v_completed_id INT;
    v_loyalty_id INT;
BEGIN
    SELECT status_id INTO v_confirmed_id FROM status_type WHERE description = 'Confirmed';
    SELECT status_id INTO v_completed_id FROM status_type WHERE description = 'Completed';

    -- Branching checking OLD and NEW states
    IF OLD.status_id = v_confirmed_id AND NEW.status_id = v_completed_id THEN
        
        SELECT loyalty_id INTO v_loyalty_id FROM loyalty WHERE customer_id = NEW.customer_id;
        
        IF FOUND THEN
            -- DML Update
            UPDATE loyalty 
            SET points = points + (NEW.party_size * 10)
            WHERE loyalty_id = v_loyalty_id;
        END IF;
        
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trgf_after_reservation_update() OWNER TO "MyUser";

--
-- TOC entry 253 (class 1255 OID 41234)
-- Name: trgf_prevent_duplicate_feedback(); Type: FUNCTION; Schema: public; Owner: MyUser
--

CREATE FUNCTION public.trgf_prevent_duplicate_feedback() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists INT;
BEGIN
    SELECT COUNT(*) INTO v_exists 
    FROM feedback 
    WHERE reservation_id = NEW.reservation_id;
    
    IF v_exists > 0 THEN
        -- Fails fast before disk writes
        RAISE EXCEPTION 'A feedback record already exists for reservation %.', NEW.reservation_id;
    END IF;
    
    RETURN NEW;
END;
$$;


