INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (1, 1, 'In congue. Etiam justo.', '2023-10-08', 37);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (2, 3, 'Etiam pretium iaculis justo.', '2025-05-27', 74);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (3, 4, 'In hac habitasse platea dictumst. Aliquam augue quam, sollicitudin vitae, consectetuer eget, rutrum at, lorem.', '2025-09-20', 111);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (4, 5, 'Nulla ac enim. In tempor, turpis nec euismod scelerisque, quam turpis adipiscing lorem, vitae mattis nibh ligula nec sem.', '2024-06-14', 148);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (5, 4, 'Phasellus id sapien in sapien iaculis congue. Vivamus metus arcu, adipiscing molestie, hendrerit at, vulputate vitae, nisl.', '2024-09-06', 185);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (6, 1, 'Fusce posuere felis sed lacus. Morbi sem mauris, laoreet ut, rhoncus aliquet, pulvinar sed, nisl.', '2025-11-07', 222);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (7, 5, 'Quisque arcu libero, rutrum ac, lobortis vel, dapibus at, diam.', '2023-09-14', 259);
INSERT INTO public.feedback (feedback_id, rating, comment, feedback_date, reservation_id) VALUES (8, 5, 'Donec semper sapien a libero.', '2024-11-12', 296);
